window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[126]={"id":"126","numero":126,"titre":"Trouble de l'érection","objectifs":[{"id":"126-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition des différents types de dysfonction érectile et leurs étiologies","contenu":"<div class=\"callout callout-info\">\n        <strong>Définition</strong>\n        <p><span class=\"kw-def\">Incapacité d'obtenir et/ou de maintenir une érection</span> suffisante pour une <span class=\"kw-clinique\">activité sexuelle satisfaisante</span>, évoluant depuis <span class=\"kw-chiffre\">&gt; 3 mois</span>.</p>\n      </div>\n      <p><strong>Trois types de dysfonction érectile (DE)</strong></p>\n      <ul>\n        <li><span class=\"kw-def\">DE psychogène</span> — origine psycho-affective prédominante.</li>\n        <li><span class=\"kw-def\">DE organique</span> — causes <span class=\"kw-etio\">artérielles</span>, <span class=\"kw-etio\">neurogéniques</span>, <span class=\"kw-etio\">hormonales</span> ou <span class=\"kw-etio\">iatrogènes</span>.</li>\n        <li><span class=\"kw-def\">DE mixte</span> — <strong>mécanisme le plus fréquent</strong> : une DE organique a presque toujours un retentissement psychologique (<span class=\"kw-clinique\">anxiété de performance</span>) qui l'aggrave.</li>\n      </ul>\n      <p><span class=\"kw-clinique\">Épidémiologie</span> : la DE touche <span class=\"kw-chiffre\">1 homme sur 3 de plus de 40 ans</span> ; l'<span class=\"kw-etio\">âge</span> est un <span class=\"kw-def\">facteur de risque</span> indépendant. Sexualité active encore estimée à <span class=\"kw-chiffre\">70 %</span> à<span class=\"kw-chiffre\"> 70 ans</span>.</p>\n\n      <div class=\"callout callout-warn\" style=\"border-left:3px solid var(--warn)\">\n        <strong>Diagnostics différentiels (à distinguer)</strong> — la DE doit être distinguée des autres troubles sexuels, souvent associés :\n        <ul>\n          <li>Troubles du <span class=\"kw-clinique\">désir</span> / de la <span class=\"kw-clinique\">libido</span>.</li>\n          <li>Troubles de l'<span class=\"kw-clinique\">éjaculation</span> (notamment éjaculation précoce, parfois secondaire à l'anxiété de performance).</li>\n          <li>Troubles de l'<span class=\"kw-clinique\">orgasme</span>.</li>\n          <li><span class=\"kw-clinique\">Douleurs lors des rapports</span>.</li>\n          <li><span class=\"kw-clinique\">Dysfonctionnement du couple</span>.</li>\n          <li><span class=\"kw-clinique\">Anomalie morphologique</span> de la verge (courbure gênant la pénétration → maladie de Lapeyronie).</li>\n        </ul>\n      </div>\n\n      <p><strong>Étiologies et facteurs favorisants</strong></p>\n      <table >\n        <thead><tr><th>Facteur</th><th>Points clés</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Âge</strong></span></td>\n            <td><span class=\"kw-def\">Facteur de risque</span> <strong>majeur</strong> : <span class=\"kw-clinique\">déficits neurosensoriels</span> progressifs, <span class=\"kw-bio\">baisse physiologique de la testostérone</span>, accumulation de <span class=\"kw-etio\">comorbidités</span> (CV, <span class=\"kw-etio\">HTA</span>, diabète, dyslipidémie, médicaments).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Maladies cardio-vasculaires</strong></span></td>\n            <td>La DE est un <span class=\"kw-alerte\">symptôme sentinelle</span> de maladie CV : <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">artères caverneuses sont obstruées avant les coronaires</span> (hypothèse du <span class=\"kw-clinique\">diamètre</span>). Une <span class=\"kw-clinique\">DE isolée peut précéder un IDM</span> et constitue un <span class=\"kw-alerte\">facteur de gravité</span> CV.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>2 causes prédominent</strong></span></td>\n            <td><strong><span class=\"kw-etio\">Diabète</span></strong> : vérifier l'<span class=\"kw-bio\">équilibre glycémique</span>, rechercher complications et autres <span class=\"kw-etio\">FRCV</span>.<br><strong><span class=\"kw-etio\">Athérosclérose</span></strong> : rechercher <span class=\"kw-clinique\">AOMI</span>, <span class=\"kw-clinique\">cardiopathie ischémique</span>, <span class=\"kw-clinique\">anévrisme de l'aorte abdominale</span>, ATCD d'<span class=\"kw-clinique\">AVC</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ci\"><strong>Médicaments</strong></span></td>\n            <td><span class=\"kw-ci\">Antidépresseurs</span>, <span class=\"kw-ci\">neuroleptiques</span>, <span class=\"kw-ci\">benzodiazépines</span> ; <span class=\"kw-ci\">inhibiteurs de la 5α-réductase</span>, <span class=\"kw-ci\">anti-androgènes</span>, stéroïdes anabolisants, kétoconazole ; anti-<span class=\"kw-etio\">HTA</span> : <span class=\"kw-ci\">thiazidiques</span>, <span class=\"kw-ci\">β-bloquants non sélectifs</span>, <span class=\"kw-ttt\">spironolactone</span>, méthyldopa, clonidine ; <span class=\"kw-ci\">fibrates</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Autres causes organiques</strong></span></td>\n            <td><strong>Génito-pelviennes :</strong> maladie de Lapeyronie, HBP <em>(mais pas le cancer de la prostate)</em>.<br><strong>Endocriniennes :</strong> <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">hypogonadisme</span>, <span class=\"kw-etio\">hyperprolactinémie</span>, dysthyroïdie.<br><strong>Neurologiques :</strong> neurodégénératives, vasculaires, médullaires.<br><strong>Chroniques :</strong> <span class=\"kw-ci\">insuffisance rénale</span>/dialyse, insuffisance cardiaque.<br><strong>Hématologiques :</strong> drépanocytose, <span class=\"kw-etio\">hémochromatose</span>.<br><strong>Addictives / psy :</strong> <span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">tabac</span>, <span class=\"kw-etio\">SAOS</span>, <span class=\"kw-etio\">dépression</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-etio\">Diabète</span> · 222 — FDR cardiovasculaire · 223 — Dyslipidémie · 224 — HTA · 225 — Artériopathie oblitérante - anévrysme · 127 — Hypertrophie de prostate bénigne</em></p>","frequence":0},{"id":"126-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les structures anatomiques et les mécanismes de l’érection","contenu":"<p>L'érection correspond à un <span class=\"kw-def\">état de rigidité des corps caverneux</span>, sous double contrôle <span class=\"kw-clinique\">vasculaire</span> et <span class=\"kw-clinique\">nerveux</span>.</p>\n\n      <p><strong>Anatomie de la verge</strong></p>\n      <table >\n        <thead><tr><th>Structure</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Corps caverneux</strong></span></td>\n            <td>2 structures cylindriques séparées par un <span class=\"kw-clinique\">septum perméable</span>, organisées en travées soutenant <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">cellules musculaires lisses</span> ; les alvéoles tapissées d'endothélium = <span class=\"kw-def\">espaces sinusoïdes</span>. L'<span class=\"kw-def\">albuginée</span> (membrane peu extensible) entoure les corps caverneux : rôle clé dans le <span class=\"kw-clinique\">mécanisme veino-occlusif</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Muscles périnéaux</strong></span></td>\n            <td><span class=\"kw-clinique\">Ischio-caverneux</span> : leur contraction volontaire ↑ la <span class=\"kw-clinique\">pression dans les corps caverneux</span>.<br><span class=\"kw-clinique\">Bulbo-spongieux</span> : contractions rythmées → <span class=\"kw-clinique\">expulsion du sperme</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Vascularisation</strong></span></td>\n            <td><strong>Artères :</strong> artères caverneuses ← <span class=\"kw-clinique\">artères pudendales internes</span> ← <span class=\"kw-clinique\">artère iliaque interne</span>.<br><strong><span class=\"kw-ttt\">Drainage</span> veineux :</strong> réseau profond → <span class=\"kw-clinique\">plexus de Santorini</span> → veines pudendales → veines iliaques internes.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Voies nerveuses</strong></p>\n      <table >\n        <thead><tr><th>Voie</th><th>Rôle</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Nerfs caverneux</strong></span></td>\n            <td>Rameaux terminaux du <span class=\"kw-clinique\">plexus hypogastrique inférieur</span> ; cheminent contre rectum et prostate, sous la symphyse pubienne, vers le hile du pénis.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Sympathique</strong></span> (moelle thoraco-lombaire)</td>\n            <td>Maintient le <span class=\"kw-clinique\">muscle lisse contracté</span> → ferme <span class=\"kw-clinique\">les</span> espaces sinusoïdes → <span class=\"kw-def\">ÉTAT FLACCIDE</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Parasympathique</strong></span> (moelle sacrée)</td>\n            <td>Libération de <span class=\"kw-bio\">monoxyde d'azote (NO)</span> → relaxation et ouverture des sinusoïdes → <span class=\"kw-def\">ÉTAT RIGIDE</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Somatique</strong></span></td>\n            <td>Motricité des muscles périnéaux ; sensibilité du gland par le <span class=\"kw-clinique\">nerf dorsal du pénis</span> → <span class=\"kw-clinique\">nerf pudendal</span> → moelle sacrée <span class=\"kw-chiffre\">S2-S3-S4</span> → déclenche <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">érections réflexes</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Contrôle supra-médullaire</strong></span></td>\n            <td><span class=\"kw-clinique\">Hypothalamus</span> (module l'équilibre) et <span class=\"kw-clinique\">cortex limbique</span> (intègre <span class=\"kw-clinique\">les</span> stimulations selon l'état psychologique).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Cascade moléculaire de l'érection</strong></p>\n      <ul>\n        <li>Stimulation → <span class=\"kw-clinique\">inhibition du tonus sympathique</span> + <span class=\"kw-clinique\">stimulation parasympathique</span> → <span class=\"kw-clinique\">les</span> nerfs caverneux libèrent du <span class=\"kw-bio\">NO</span>.</li>\n        <li>Le <span class=\"kw-bio\">NO</span> ↑ la <span class=\"kw-bio\">GMP cyclique (GMPc)</span> intracellulaire ; la <span class=\"kw-bio\">phosphodiestérase de type 5 (PDE5)</span> dégrade la GMPc → <strong>cible des inhibiteurs de PDE5</strong>.</li>\n        <li>Relaxation des cellules musculaires lisses → ouverture des espaces sinusoïdes → afflux de sang artériel → <span class=\"kw-clinique\">rigidité</span>.</li>\n        <li>Compression des <span class=\"kw-clinique\">veines sous-albuginéales</span> → <span class=\"kw-def\">mécanisme veino-occlusif passif</span> (blocage du retour veineux).</li>\n        <li><span class=\"kw-clinique\">Les</span> cellules endothéliales étirées sécrètent du <span class=\"kw-bio\">NO</span> → <span class=\"kw-clinique\">maintien de l'érection</span> (défaillant dans la <span class=\"kw-alerte\">dysfonction endothéliale</span> : <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">HTA</span>, <span class=\"kw-etio\">dyslipidémie</span>, <span class=\"kw-etio\">tabac</span>).</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Trois types d'érection</strong> (mécanisme identique, stimulation différente)\n        <ul>\n          <li><span class=\"kw-clinique\">Nocturne</span> — accompagne le sommeil paradoxal.</li>\n          <li><span class=\"kw-clinique\">Réflexe</span> — stimulation locale, dépend du <span class=\"kw-clinique\">nerf dorsal du pénis</span> (perdue si <span class=\"kw-clinique\">lésion</span> bilatérale lors d'une fracture du bassin).</li>\n          <li><span class=\"kw-clinique\">Psychogène</span> — stimulation cérébrale parvenant à l'hypothalamus (visuelle, auditive, fantasmatique).</li>\n        </ul>\n      </div>","frequence":0},{"id":"126-3","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir faire le bilan clinique d’une dysfonction érectile","contenu":"<div class=\"callout callout-info\">\n        <strong>L'interrogatoire suffit au <span class=\"kw-def\">diagnostic positif</span>.</strong> <span class=\"kw-clinique\">Les</span> patients abordent rarement le sujet spontanément mais répondent aux questions simples (« avez-vous un manque de rigidité pendant les rapports ? ») — à rechercher systématiquement chez tout patient avec une maladie CV ou des <span class=\"kw-etio\">FRCV</span>.\n      </div>\n\n      <p><strong>1. Caractériser la dysfonction érectile</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Primaire</span> (depuis le début de la vie sexuelle) ou <span class=\"kw-clinique\">secondaire</span>.</li>\n        <li><span class=\"kw-clinique\">Inaugural</span> ou <span class=\"kw-clinique\">réactionnel</span> à un autre trouble sexuel.</li>\n        <li><span class=\"kw-clinique\">Brutal</span> (facteur déclenchant ?) ou <span class=\"kw-clinique\">progressif</span>.</li>\n        <li><span class=\"kw-clinique\">Permanent</span> ou <span class=\"kw-clinique\">situationnel</span> (selon le partenaire ?).</li>\n        <li>Persistance des <span class=\"kw-clinique\">érections nocturnes et/ou matinales</span> ?</li>\n      </ul>\n\n      <p><strong>2. Évaluer la sévérité</strong></p>\n      <table >\n        <thead><tr><th>Outil</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Erection Hardness Score (EHS)</strong></span></td>\n            <td>Évaluation simple de la rigidité, de <span class=\"kw-chiffre\">0</span> (absence d'érection) à <span class=\"kw-chiffre\">4</span> (pénis complètement dur).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Auto-questionnaire IIEF</strong></span><br>(version courte)</td>\n            <td>Classe la DE en grades : <span class=\"kw-chiffre\">sévère 5-10</span> · <span class=\"kw-chiffre\">modérée 11-15</span> · <span class=\"kw-chiffre\">modérée à légère 16-21</span> · <span class=\"kw-chiffre\">légère 22-25</span> · <span class=\"kw-chiffre\">normale 26-30</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Pronostic</strong></span></td>\n            <td>Délai apparition-consultation long = prise en charge plus difficile ; <span class=\"kw-clinique\">capacité érectile résiduelle</span> et <span class=\"kw-clinique\">érections nocturnes/matinales conservées</span> = facteurs de bon <span class=\"kw-def\">pronostic</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>3. Orienter l'étiologie</strong> — organique <span class=\"kw-bio\">vs</span> psychogène <em>(à distinguer)</em></p>\n      <table >\n        <thead><tr><th>Caractéristique</th><th>Origine organique</th><th>Origine psychogène</th></tr></thead>\n        <tbody>\n          <tr><td>Mode de début</td><td><span class=\"kw-clinique\">Progressif</span></td><td><span class=\"kw-clinique\">Brutal</span></td></tr>\n          <tr><td>Facteur déclenchant</td><td>Absent</td><td>Présent (naissance, mariage, promotion…)</td></tr>\n          <tr><td>Érections nocturnes</td><td><span class=\"kw-alerte\">Disparues</span></td><td><span class=\"kw-clinique\">Conservées</span></td></tr>\n          <tr><td>Libido</td><td>Conservée (sauf hypogonadisme)</td><td>Diminuée</td></tr>\n          <tr><td>Contexte</td><td>Étiologie organique évidente, partenaire stable</td><td>Conflits conjugaux, dépression, anxiété</td></tr>\n          <tr><td>Examen / paraclinique</td><td><span class=\"kw-bio\">Anormaux</span></td><td><span class=\"kw-bio\">Normaux</span></td></tr>\n        </tbody>\n      </table>\n      <p>Rechercher des arguments psychogènes : <span class=\"kw-clinique\">histoire sexuelle</span>, raison de la consultation, <span class=\"kw-clinique\">contexte affectif et de couple</span>, <span class=\"kw-clinique\">anxiété de performance</span>, <span class=\"kw-clinique\">événements de vie</span> (positifs ou négatifs) dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span> précédents.</p>\n\n      <p><strong>4. Examen clinique</strong></p>\n      <ul>\n        <li><strong>OGE :</strong> taille/consistance des <span class=\"kw-clinique\">testicules</span> ; examen du pénis (<span class=\"kw-clinique\">plaques de Lapeyronie</span>, courbure, hypospadias/épispadias, fibrose des corps caverneux, pénis enfoui).</li>\n        <li>Rechercher une <span class=\"kw-clinique\">gynécomastie</span>, apprécier la <span class=\"kw-clinique\">pilosité</span>.</li>\n        <li><strong>Cardio-vasculaire :</strong> <span class=\"kw-clinique\">TA</span>, <span class=\"kw-clinique\">pouls périphériques</span>, auscultation, périmètre abdominal.</li>\n        <li><strong>Neurologique :</strong> ROT, réflexes cutanéo-plantaires, <span class=\"kw-alerte\">anesthésie en selle</span>.</li>\n        <li><strong>TR si &gt;<span class=\"kw-chiffre\"> 50 ans</span></strong> (ou <span class=\"kw-chiffre\">45 ans</span> si ATCD familiaux) → recherche d'<span class=\"kw-clinique\">HBP</span> ou de <span class=\"kw-alerte\">cancer de la prostate</span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 127 — Hypertrophie de prostate bénigne · 310 — Tumeur prostate</em></p>","frequence":2},{"id":"126-4","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer une maladie de Lapeyronie","contenu":"<div class=\"callout callout-info\">\n        <strong>Définition</strong>\n        <p><span class=\"kw-def\">Fibrose localisée de l'albuginée</span> formant une <span class=\"kw-clinique\">plaque</span> qui donne une <span class=\"kw-clinique\">courbure de la verge en érection</span>. Affection <strong>bénigne</strong>, d'étiologie inconnue (décrite par Lapeyronie, chirurgien de Louis XV).</p>\n      </div>\n      <p><strong><span class=\"kw-def\">Épidémiologie</span></strong></p>\n      <ul>\n        <li>Observée chez <span class=\"kw-chiffre\">3 à 9 %</span> des hommes.</li>\n        <li><span class=\"kw-def\">Prévalence</span> plus élevée chez <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">diabétiques</span> (<span class=\"kw-chiffre\">10 %</span>) et après <span class=\"kw-etio\">prostatectomie radicale</span> (<span class=\"kw-chiffre\">15 %</span>).</li>\n      </ul>\n      <p><strong>Histoire naturelle</strong> — deux phases successives :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Phase inflammatoire</span> : <span class=\"kw-clinique\">plaque</span> <em>de novo</em> + <span class=\"kw-clinique\">douleurs</span>.</li>\n        <li><span class=\"kw-clinique\">Phase cicatricielle</span> : stabilisation.</li>\n      </ul>\n      <p><strong>Démarche diagnostique</strong></p>\n      <ul>\n        <li>Diagnostic <span class=\"kw-def\">clinique</span> : <span class=\"kw-clinique\">palpation des plaques</span>, examen de la verge, <span class=\"kw-imagerie\">photographie du pénis en érection</span>.</li>\n        <li>Apprécier le <span class=\"kw-clinique\">retentissement</span> : courbure importante empêchant l'intromission, <span class=\"kw-clinique\">dysfonction érectile</span> associée, retentissement psychologique.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Aucun examen complémentaire requis.</strong> L'<span class=\"kw-imagerie\">IRM</span> et l'<span class=\"kw-imagerie\">écho-doppler</span> de la verge ne sont réservés qu'aux cas complexes (piège classique).\n      </div>","frequence":0},{"id":"126-5","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir identifier un priapisme","contenu":"<div class=\"callout callout-info\">\n        <strong>Définition</strong>\n        <p><span class=\"kw-def\">Érection involontaire et prolongée</span> de <span class=\"kw-chiffre\">&gt; 4 heures</span>, en général <span class=\"kw-clinique\">douloureuse</span>, survenant <strong>en dehors de toute stimulation sexuelle</strong>.</p>\n      </div>\n\n      <p><strong>Deux mécanismes à distinguer en <span class=\"kw-alerte\">urgence</span></strong></p>\n      <table >\n        <thead><tr><th>Caractéristique</th><th>Priapisme <span class=\"kw-etio\">ischémique</span></th><th>Priapisme non ischémique</th></tr></thead>\n        <tbody>\n          <tr><td>Fréquence</td><td><strong>Le plus fréquent</strong></td><td>Rare</td></tr>\n          <tr><td>Degré d'<span class=\"kw-alerte\">urgence</span></td><td><span class=\"kw-alerte\">Urgence thérapeutique</span> (<span class=\"kw-def\">pronostic</span> fonctionnel engagé)</td><td><span class=\"kw-alerte\">Urgence</span> relative</td></tr>\n          <tr><td>Débit / mécanisme</td><td><span class=\"kw-clinique\">Bas débit, veino-occlusif</span></td><td><span class=\"kw-clinique\">Haut débit, artériel</span></td></tr>\n          <tr><td>Cause</td><td>Dysfonction du muscle lisse ou hyperviscosité → stase veineuse</td><td><span class=\"kw-etio\">Traumatisme</span> (chute à califourchon) → <span class=\"kw-clinique\">fistule artério-caverneuse</span></td></tr>\n          <tr><td>Clinique</td><td>Corps caverneux <span class=\"kw-clinique\">rigides et douloureux</span> ; gland flaccide</td><td>Érection <span class=\"kw-clinique\">non douloureuse</span>, partielle/molle (non hypoxiante)</td></tr>\n          <tr><td><span class=\"kw-bio\">Gaz du sang</span> caverneux</td><td><span class=\"kw-bio\">PaO₂ &lt; 30 mmHg</span>, <span class=\"kw-bio\">PaCO₂ &gt; 60 mmHg</span>, <span class=\"kw-bio\">pH &lt; 7,25</span> (hypoxie + acidose)</td><td><span class=\"kw-bio\">PaO₂ &gt; 50 mmHg</span>, <span class=\"kw-bio\">PaCO₂ &lt; 40 mmHg</span>, <span class=\"kw-bio\">pH &gt; 7,35</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">Écho-doppler</span> verge</td><td><span class=\"kw-imagerie\">Disparition du flux des artères caverneuses</span></td><td><span class=\"kw-imagerie\">Fistule artério-caverneuse</span> (si traumatisme)</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Démarche d'identification</strong></p>\n      <ul>\n        <li>Évaluation clinique : <span class=\"kw-clinique\">tumescence douloureuse</span>, <span class=\"kw-clinique\">durée</span> de l'érection, recherche d'un <span class=\"kw-etio\">traumatisme</span>, <span class=\"kw-clinique\">fonction érectile préexistante</span>, ATCD de priapisme ou d'<span class=\"kw-etio\">hémoglobinopathie</span>, usage de <span class=\"kw-etio\">thérapies érectogènes</span> (IIC, iPDE5).</li>\n        <li>Le <span class=\"kw-bio\">gaz du sang caverneux</span> fait la distinction <span class=\"kw-etio\">ischémique</span> / non ischémique.</li>\n        <li>L'<span class=\"kw-imagerie\">écho-doppler de la verge</span> n'est utile qu'en cas de doute clinique.</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong>Pourquoi c'est une <span class=\"kw-alerte\">urgence</span> (priapisme <span class=\"kw-etio\">ischémique</span>)</strong>\n        <ul>\n          <li>Au-delà de <span class=\"kw-chiffre\">4 h</span> : hypoxie + acidose (visibles au <span class=\"kw-bio\">GDS</span> dès <span class=\"kw-chiffre\">6 h</span>) + glucopénie.</li>\n          <li>→ <span class=\"kw-alerte\">nécrose des cellules musculaires lisses</span> → <span class=\"kw-alerte\">fibrose séquellaire</span> → dysfonction érectile définitive + perte de longueur.</li>\n          <li>Après <span class=\"kw-chiffre\">&gt; 24 h</span> : <span class=\"kw-alerte\">90 %</span> des hommes (priapisme <span class=\"kw-etio\">ischémique</span>) n'ont plus de fonction érectile permettant des rapports.</li>\n        </ul>\n      </div>\n      <p>Le <span class=\"kw-clinique\">priapisme récidivant / intermittent</span> (épisodes <span class=\"kw-chiffre\">&lt; 3 h</span>) peut évoluer vers un priapisme <span class=\"kw-etio\">ischémique</span>, typiquement chez le <span class=\"kw-etio\">drépanocytaire</span>.</p>","frequence":0},{"id":"126-6","rang":"B","rubrique":"Etiologies","titre":"Connaître les causes du priapisme","contenu":"<p><span class=\"kw-clinique\">Les</span> causes du priapisme se répartissent en grandes familles ; l'<span class=\"kw-etio\">origine idiopathique</span> domine.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Idiopathique</strong></span></td>\n            <td><span class=\"kw-chiffre\">30 à 50 %</span> des cas.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Iatrogène</strong></span></td>\n            <td><span class=\"kw-ci\">Injections intracaverneuses +++</span> (prostaglandines E1), <span class=\"kw-ci\">psychotropes</span>, anesthésiques.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Toxiques</strong></span></td>\n            <td><span class=\"kw-etio\">Cocaïne</span>, intoxication alcoolique aiguë.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Hématologiques</strong></span></td>\n            <td><span class=\"kw-etio\">Drépanocytose</span> (<span class=\"kw-chiffre\">30-40 %</span> de risque de priapisme), <span class=\"kw-etio\">LMC</span>, troubles de la coagulation.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Tumorales</strong></span></td>\n            <td>Tumeur caverneuse (primitive ou métastatique), compression extrinsèque.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Neurologiques</strong></span></td>\n            <td><span class=\"kw-etio\">Lésions médullaires</span>, tumeurs cérébrales, épilepsie.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Traumatiques</strong></span></td>\n            <td>Traumatisme du <span class=\"kw-clinique\">pénis</span> ou du <span class=\"kw-clinique\">périnée</span> (→ priapisme non <span class=\"kw-etio\">ischémique</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie</em></p>","frequence":1},{"id":"126-7","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître le bilan de première intention d’une dysfonction érectile","contenu":"<div class=\"callout callout-info\">\n        Le <strong><span class=\"kw-def\">diagnostic positif</span> de DE est clinique</strong> (interrogatoire). Le bilan paraclinique de 1ʳᵉ intention vise à dépister <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">FRCV</span> et <span class=\"kw-def\">comorbidités</span> sous-jacentes, pas à confirmer la DE.\n      </div>\n      <p><strong>Bilan <span class=\"kw-ttt\">biologique</span> minimal recommandé</strong></p>\n      <table >\n        <thead><tr><th>Situation</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Systématique</strong></span></td>\n            <td><span class=\"kw-bio\">Glycémie à jeun</span> + <span class=\"kw-bio\">bilan lipidique</span> (<span class=\"kw-bio\">cholestérol total</span>, <span class=\"kw-bio\">HDL</span>, <span class=\"kw-bio\">triglycérides</span>).</td>\n          </tr>\n          <tr>\n            <td>Si <span class=\"kw-etio\">diabétique</span></td>\n            <td>Ajout de l'<span class=\"kw-bio\">HbA1c</span>.</td>\n          </tr>\n          <tr>\n            <td>Si <span class=\"kw-chiffre\">&gt; 50 ans</span> + signes de <span class=\"kw-clinique\">déficit en testostérone</span></td>\n            <td><span class=\"kw-bio\">Testostéronémie totale et biodisponible</span>.</td>\n          </tr>\n          <tr>\n            <td>Selon examen prostatique ou si androgénothérapie envisagée</td>\n            <td>Dosage du <span class=\"kw-bio\">PSA total</span>.</td>\n          </tr>\n          <tr>\n            <td>En l'absence de bilan récent (<span class=\"kw-chiffre\">&lt; 5 ans</span>)</td>\n            <td><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">bilan hépatique</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-etio\">Diabète</span> · 223 — Dyslipidémie · 310 — Tumeur prostate</em></p>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré d'<span class=\"kw-alerte\">urgence</span> :</strong> le <span class=\"kw-etio\">priapisme ischémique</span> est une <span class=\"kw-alerte\">urgence thérapeutique</span> au <span class=\"kw-alerte\">pronostic fonctionnel engagé</span> ; la dysfonction érectile et la maladie de Lapeyronie ne sont pas des urgences.<br><strong>Fenêtre thérapeutique :</strong> érection involontaire prolongée <span class=\"kw-chiffre\">&gt; 4 h</span> ; <span class=\"kw-clinique\">hypoxie</span> et <span class=\"kw-clinique\">acidose</span> caverneuses dès <span class=\"kw-chiffre\">6 h</span> ; au-delà de <span class=\"kw-chiffre\">24 h</span> la fonction résiduelle ne permet plus de rapports chez <span class=\"kw-alerte\">90 % des hommes</span>.<br><strong>1er geste :</strong> <span class=\"kw-ttt\">ponction-aspiration des corps caverneux</span> (aiguille <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>19</span>G</span>) + <span class=\"kw-bio\">gaz du sang caverneux</span> pour confirmer le diagnostic et distinguer le mécanisme.</p>","hospit":"<p><strong>Priapisme <span class=\"kw-etio\">ischémique</span> :</strong> <span class=\"kw-alerte\">urgence urologique</span>, prise en charge <span class=\"kw-alerte\">hospitalière immédiate</span> (gestes spécialisés successifs).<br><strong>Priapisme non ischémique :</strong> <span class=\"kw-alerte\">urgence</span> relative — <span class=\"kw-def\">surveillance</span> ou <span class=\"kw-ttt\">embolisation sélective</span>.<br><strong>Dysfonction érectile — cas simple :</strong> prise en charge en médecine générale.<br><strong>Dysfonction érectile — cas complexe :</strong> <span class=\"kw-ttt\">avis spécialisé</span> (urologue, andrologue, endocrinologue, sexologue).<br><strong>Maladie de Lapeyronie :</strong> diagnostic clinique, prise en charge spécialisée si répercussions.</p>","redflags":"<ul><li>Érection prolongée <span class=\"kw-chiffre\">&gt; 4 h</span>, <span class=\"kw-clinique\">douloureuse</span> avec corps caverneux <span class=\"kw-clinique\">rigides</span> et gland flaccide → <span class=\"kw-etio\">priapisme ischémique</span></li><li><span class=\"kw-bio\">Gaz du sang</span> caverneux : <span class=\"kw-chiffre\">PaO2 &lt; 30 mmHg</span>, <span class=\"kw-chiffre\">PaCO2 &gt; 60 mmHg</span>, <span class=\"kw-chiffre\">pH &lt; 7,25</span></li><li><span class=\"kw-radio\">Disparition complète du flux des artères caverneuses</span> à l'<span class=\"kw-imagerie\">écho-Doppler de la verge</span></li><li>Dysfonction érectile = <span class=\"kw-alerte\">symptôme sentinelle</span> d'une maladie cardiovasculaire (<span class=\"kw-etio\">coronaropathie</span>)</li><li><span class=\"kw-etio\">Drépanocytose</span> : <span class=\"kw-chiffre\">30-40 %</span> de risque de priapisme</li><li>Prise de <span class=\"kw-ci\">dérivés nitrés</span> ou de donneurs de NO (<span class=\"kw-ci\">nicorandil</span>, <span class=\"kw-ci\">molsidomine</span>) : <span class=\"kw-ci\">contre-indication</span> des <span class=\"kw-ttt\">IPDE5</span> (<span class=\"kw-alerte\">hypotension mortelle chez le coronarien</span>)</li></ul>","principes":"<p>Trois entités, trois logiques : <span class=\"kw-alerte\">urgence</span> pour le <span class=\"kw-etio\">priapisme</span>, prise en charge stratifiée pour la <span class=\"kw-etio\">dysfonction érectile</span>, attitude conservatrice pour la <span class=\"kw-etio\">maladie de Lapeyronie</span>.</p><p><strong>Priapisme <span class=\"kw-etio\">ischémique</span> — <span class=\"kw-alerte\">urgence</span></strong></p><p>Algorithme : <span class=\"kw-chiffre\">&lt; 36 h</span> → aspiration-lavage + sympathomimétique ± <span class=\"kw-ttt\">chirurgie</span> · <span class=\"kw-chiffre\">&gt; 36 h</span> → implant pénien</p><ul><li>Techniques simples induisant une vasoconstriction : glace, bain d'eau froide, éjaculation</li><li>Si <span class=\"kw-clinique\">évolution</span> <span class=\"kw-chiffre\">&lt; 4 h</span> : <span class=\"kw-ttt\">étiléfrine PO</span> (sympathomimétique oral)</li><li><span class=\"kw-ttt\">Ponction-aspiration</span> (aiguille <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>19</span>G</span>) jusqu'à l'obtention de sang artériel rouge</li><li><span class=\"kw-ttt\">Injection intracaverneuse de phényléphrine</span> (α-adrénergique sélectif) sous scope ; réponse moins bonne après <span class=\"kw-chiffre\">24 h</span></li><li><span class=\"kw-ttt\">Shunt caverno-spongieux</span> puis <span class=\"kw-ttt\">prothèse pénienne</span> si priapisme <span class=\"kw-chiffre\">&gt; 72 h</span></li></ul><p><strong>Priapisme non <span class=\"kw-etio\">ischémique</span></strong></p><ul><li><span class=\"kw-alerte\">Urgence</span> relative ; aspiration à visée diagnostique</li><li><span class=\"kw-def\">Surveillance</span>, <span class=\"kw-ttt\">compression prolongée de la fistule</span> (enfant)</li><li><span class=\"kw-ttt\">Embolisation sélective</span> si priapisme artériel persistant</li></ul><p><strong>Dysfonction érectile — par intention</strong></p><p><span class=\"kw-ttt\">IPDE5</span> <span class=\"kw-ci\">contre-indiqués avec les dérivés nitrés et les donneurs de NO</span> et si <span class=\"kw-ci\">cardiopathie sévère non stabilisée</span></p><ul><li>1re intention : <span class=\"kw-ttt\">IPDE5</span> + hygiène de vie + soutien psychologique + avis cardiovasculaire</li><li><span class=\"kw-chiffre\">2e intention</span> : <span class=\"kw-ttt\">prostaglandines (alprostadil)</span> en injection intracaverneuse ou intra-urétrale</li><li><span class=\"kw-chiffre\">3e ligne</span> : <span class=\"kw-ttt\">implants péniens</span></li></ul><p><strong>Maladie de Lapeyronie</strong></p><ul><li>Phase <span class=\"kw-etio\">inflammatoire</span> : aucun traitement n'a montré d'efficacité sur la courbure</li><li>Phase cicatricielle (si répercussions) : <span class=\"kw-ttt\">collagénase intra-plaque (Xiapex)</span> ou <span class=\"kw-ttt\">chirurgie correctrice</span> (plicature / incision-greffe)</li><li><span class=\"kw-ttt\">Photographie pré-opératoire</span> indispensable (valeur médico-légale)</li></ul>","suivi":"<p><strong>DE — cas simple :</strong> succès → fin de prise en charge ; échec → adaptation thérapeutique ; nouvel échec → <span class=\"kw-ttt\">orientation vers un spécialiste</span>.<br><strong>Priapisme :</strong> <span class=\"kw-clinique\">surveillance hémodynamique</span> et scope lors des injections de sympathomimétiques.<br><strong>Séquelles à dépister :</strong> <span class=\"kw-etio\">fibrose séquellaire</span> → <span class=\"kw-etio\">dysfonction érectile</span> et perte de longueur après priapisme <span class=\"kw-etio\">ischémique</span> prolongé.<br><strong>Bilan minimal de la DE :</strong> <span class=\"kw-bio\">glycémie à jeun</span> + <span class=\"kw-bio\">bilan lipidique</span> systématiques ; rechercher <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">facteurs de risque</span> cardiovasculaire.</p>"},"liensGlobaux":[{"href":"https://www.urofrance.org/lafu-academie/formation-du-college/referentiel-du-college-durologie-6eme-edition/chapitre-9-item-126-troubles-de-lerection/","label":"Collège d'Urologie — Item 126 Troubles de l'érection"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Trouble de l'érection — Caractériser le trouble avant tout","detail":"<h4>CAT — Trouble de l'érection — Trier l'<span class=\"kw-alerte\">urgence</span> (priapisme) puis orienter dysfonction érectile et maladie de Lapeyronie</h4>","branches":[{"to":"q-priapisme","label":"Caractériser","color":"blue"}]},{"id":"q-priapisme","kind":"decision","label":"Érection involontaire prolongée > 4 h, douloureuse, hors stimulation sexuelle ? — Suspicion de priapisme","branches":[{"to":"q-mecanisme","label":"Oui — érection > 4 h douloureuse","color":"red"},{"to":"q-type-trouble","label":"Non","color":"blue"}]},{"id":"q-mecanisme","kind":"decision","label":"Ponction-aspiration + gaz du sang caverneux — Distinguer le mécanisme ischémique du non-ischémique","branches":[{"to":"q-delai","label":"PaO2 < 30 mmHg · rigide, douloureux","color":"red"},{"to":"t-non-ischemique","label":"PaO2 > 50 mmHg · indolore · traumatisme","color":"amber"}]},{"id":"q-delai","kind":"decision","label":"Priapisme ischémique : délai d'évolution ?","branches":[{"to":"t-ischemique-precoce","label":"< 36 h","color":"red"},{"to":"t-prothese","label":"> 36 h","color":"red"}]},{"id":"t-ischemique-precoce","kind":"terminal","label":"Priapisme <span class=\"kw-etio\">ischémique</span> <span class=\"kw-chiffre\">< 36</span> h — désobstruction","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Ponction-aspiration et lavage</span> des corps caverneux (aiguille <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>19</span>G</span>)</li><li><span class=\"kw-ttt\">Injection intracaverneuse de phényléphrine</span> (α-adrénergique sélectif) sous <span class=\"kw-clinique\">surveillance hémodynamique</span> et scope</li><li>Répétition des aspirations/injections si nécessaire, puis <span class=\"kw-ttt\">shunt caverno-spongieux</span> en cas d'échec</li></ul><h4>Délai</h4><ul><li>Réponse aux sympathomimétiques <span class=\"kw-alerte\">moins bonne après 24 h</span></li></ul>"},{"id":"t-prothese","kind":"terminal","label":"Priapisme ischémique > 36 h — implant pénien","color":"red","detail":"<h4>Traitement</h4><ul><li>Mise en place d'un <span class=\"kw-ttt\">implant pénien</span> pour un priapisme évoluant depuis <span class=\"kw-chiffre\">&gt; 36 h</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Risque de <span class=\"kw-etio\">fibrose séquellaire</span> → <span class=\"kw-etio\">dysfonction érectile</span> et perte de longueur</li></ul>"},{"id":"t-non-ischemique","kind":"terminal","label":"Priapisme non ischémique — urgence relative","color":"amber","detail":"<h4>Clinique</h4><ul><li>Érection <span class=\"kw-clinique\">indolore</span>, partielle/molle, contexte de <span class=\"kw-etio\">traumatisme</span> (chute à califourchon)</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Gaz du sang</span> : <span class=\"kw-chiffre\">PaO2 &gt; 50 mmHg</span>, <span class=\"kw-chiffre\">pH &gt; 7,35</span></li><li><span class=\"kw-radio\">Fistule artério-caverneuse</span> à l'<span class=\"kw-imagerie\">écho-Doppler de la verge</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-def\">Surveillance</span>, <span class=\"kw-ttt\">compression prolongée de la fistule</span> (enfant)</li><li><span class=\"kw-ttt\">Embolisation sélective</span> si priapisme artériel persistant</li></ul>"},{"id":"q-type-trouble","kind":"decision","label":"Courbure de la verge en érection + plaque albuginéale palpable ? — Hors contexte de priapisme","branches":[{"to":"t-lapeyronie","label":"Oui — plaque + courbure","color":"blue"},{"to":"q-complexite","label":"Non — DE > 3 mois","color":"blue"}]},{"id":"t-lapeyronie","kind":"terminal","label":"Maladie de Lapeyronie","color":"blue","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Plaque albuginéale palpable</span> et <span class=\"kw-clinique\">courbure de la verge en érection</span></li><li><span class=\"kw-ttt\">Photo du pénis en érection</span> (valeur médico-légale)</li></ul><h4>Paraclinique</h4><ul><li>Diagnostic clinique : aucun examen complémentaire requis (<span class=\"kw-imagerie\">IRM</span> / <span class=\"kw-imagerie\">écho-Doppler</span> seulement si cas complexe)</li></ul><h4>Traitement</h4><ul><li>Phase cicatricielle si répercussions : <span class=\"kw-ttt\">collagénase intra-plaque (Xiapex)</span> ou <span class=\"kw-ttt\">chirurgie correctrice</span></li></ul>"},{"id":"q-complexite","kind":"decision","label":"Dysfonction érectile > 3 mois : critères de cas simple ? — DE secondaire, isolée, capacité résiduelle, sans conjugopathie","branches":[{"to":"t-de-mg","label":"Oui (cas simple)","color":"green"},{"to":"t-de-spe","label":"Non (cas complexe)","color":"amber"}]},{"id":"t-de-mg","kind":"terminal","label":"Prise en charge en médecine générale","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Hygiène de vie</span> (<span class=\"kw-ttt\">sevrage</span> tabagique, activité physique) et soutien psychologique</li><li>Traitement oral par <span class=\"kw-ttt\">IPDE5</span> — <span class=\"kw-ci\">contre-indiqués avec les dérivés nitrés</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Succès → fin de prise en charge ; échec → adaptation ; nouvel échec → orientation spécialisée</li></ul>"},{"id":"t-de-spe","kind":"terminal","label":"Avis spécialisé (urologue / andrologue / endocrinologue / sexologue)","color":"amber","detail":"<h4>Conduite</h4><ul><li>Pas de prescription immédiate ; <span class=\"kw-ttt\">avis spécialisé</span></li><li>Indiqué si <span class=\"kw-etio\">cause organique sévère</span>, échec des traitements initiaux ou <span class=\"kw-etio\">conjugopathie</span></li></ul>"}]},"cards":[{"i":"1a5fea1c67e4","n":126,"o":"126-1","u":"Définition","t":"Connaître la définition des différents types de dysfonction érectile et leurs étiologies","q":"Quelle est la définition d'une dysfonction érectile (DE) ?","a":"<p>La dysfonction érectile (DE) se définit par l'<strong>incapacité</strong> d'obtenir et/ou de maintenir une <strong>érection suffisante</strong> pour une activité sexuelle satisfaisante, évoluant depuis <strong>plus de 3 mois</strong>.</p>"},{"i":"4acd9e957c90","n":126,"o":"126-1","u":"Définition","t":"Connaître la définition des différents types de dysfonction érectile et leurs étiologies","q":"Quelles sont les principales étiologies organiques de la dysfonction érectile (DE) ?","a":"<ul><li><strong>Cardiovasculaires</strong> : diabète (mauvais équilibre glycémique), athérosclérose (AOMI, cardiopathie ischémique, anévrisme de l'aorte, ATCD d'AVC).</li><li><strong>Génito-pelviennes</strong> : maladie de Lapeyronie, HBP.</li><li><strong>Endocriniennes</strong> : hypogonadisme, hyperprolactinémie, dysthyroïdie.</li><li><strong>Neurologiques</strong> : maladies neurodégénératives, vasculaires, médullaires.</li><li><strong>Chroniques</strong> : insuffisance rénale/dialyse, insuffisance cardiaque.</li><li><strong>Hématologiques</strong> : drépanocytose, hémochromatose.</li></ul>"},{"i":"6579644dd348","n":126,"o":"126-1","u":"Définition","t":"Connaître la définition des différents types de dysfonction érectile et leurs étiologies","q":"Quels sont les trois types de dysfonction érectile (DE) et leurs caractéristiques principales ?","a":"<ul><li>La <strong>DE psychogène</strong> : l'origine est principalement psycho-affective.</li><li>La <strong>DE organique</strong> : due à des causes artérielles, neurogéniques, hormonales ou iatrogènes.</li><li>La <strong>DE mixte</strong> : le mécanisme le plus fréquent, où une DE organique est aggravée par un retentissement psychologique (anxiété de performance).</li></ul>"},{"i":"de08238066d8","n":126,"o":"126-1","u":"Définition","t":"Connaître la définition des différents types de dysfonction érectile et leurs étiologies","q":"Quels sont les médicaments susceptibles d'être à l'origine d'une dysfonction érectile (DE) ?","a":"<ul><li>Les <strong>antidépresseurs</strong>, neuroleptiques, benzodiazépines.</li><li>Les inhibiteurs de la <strong>5α-réductase</strong>, anti-androgènes, stéroïdes anabolisants, kétoconazole.</li><li>Certains <strong>anti-HTA</strong> : thiazidiques, bêta-bloquants non sélectifs, spironolactone, méthyldopa, clonidine.</li><li>Les <strong>fibrates</strong>.</li></ul>"},{"i":"ec77609c2001","n":126,"o":"126-1","u":"Définition","t":"Connaître la définition des différents types de dysfonction érectile et leurs étiologies","q":"Une dysfonction érectile (DE) peut-elle être un marqueur d'une maladie cardiovasculaire ?","a":"<p>Oui, la DE est considérée comme un <strong>symptôme sentinelle</strong> (ou « lanceur d'alerte ») de maladie cardiovasculaire. Les artères caverneuses étant de plus petit diamètre, elles sont souvent obstruées avant les artères coronaires. Une DE isolée peut ainsi précéder un infarctus du myocarde (IDM) et est un <strong>facteur de gravité cardiovasculaire</strong>.</p>"},{"i":"f2e2eee2edcf","n":126,"o":"126-1","u":"Définition","t":"Connaître la définition des différents types de dysfonction érectile et leurs étiologies","q":"Quels sont les diagnostics différentiels à distinguer de la dysfonction érectile (DE) ?","a":"<ul><li>Les troubles du <strong>désir/libido</strong>.</li><li>Les troubles de l'<strong>éjaculation</strong> (notamment l'éjaculation précoce).</li><li>Les troubles de l'<strong>orgasme</strong>.</li><li>Les <strong>douleurs</strong> lors des rapports.</li><li>Le <strong>dysfonctionnement du couple</strong>.</li><li>Les anomalies morphologiques de la verge comme la <strong>maladie de Lapeyronie</strong>.</li></ul>"},{"i":"0519e0d1bd61","n":126,"o":"126-5","u":"Identifier une urgence","t":"Savoir identifier un priapisme","q":"Comment différencier cliniquement un priapisme ischémique d'un priapisme non ischémique ?","a":"<ul><li>Dans le <strong>priapisme ischémique</strong>, les corps caverneux sont <strong>rigides et douloureux</strong>, avec un gland flaccide.</li><li>Dans le <strong>priapisme non ischémique</strong>, l'érection est généralement <strong>non douloureuse</strong>, partielle ou molle.</li></ul>"},{"i":"15c87353c425","n":126,"o":"126-5","u":"Identifier une urgence","t":"Savoir identifier un priapisme","q":"Pourquoi un priapisme ischémique constitue-t-il une urgence thérapeutique absolue ?","a":"<p>Le <strong>priapisme ischémique</strong> est une urgence thérapeutique car, au-delà de <strong>4 heures</strong>, l'hypoxie, l'acidose et la glucopénie qu'il entraîne peuvent provoquer une <strong>nécrose des cellules musculaires lisses</strong> des corps caverneux. Cela conduit à une <strong>fibrose séquellaire</strong>, une <strong>dysfonction érectile définitive</strong> et une perte de longueur pénienne. Après plus de <strong>24 heures</strong>, <strong>90%</strong> des hommes peuvent perdre toute fonction érectile.</p>"},{"i":"29cecdec2c82","n":126,"o":"126-5","u":"Identifier une urgence","t":"Savoir identifier un priapisme","q":"Quels sont les deux principaux types de priapisme à distinguer en urgence, et quelle est leur fréquence respective ?","a":"<ul><li>Le <strong>priapisme ischémique</strong> (ou à bas débit), qui est le <strong>plus fréquent</strong>.</li><li>Le <strong>priapisme non ischémique</strong> (ou à haut débit), qui est <strong>rare</strong>.</li></ul>"},{"i":"5734a6ed036d","n":126,"o":"126-5","u":"Identifier une urgence","t":"Savoir identifier un priapisme","q":"Quelle est la définition du priapisme ?","a":"<p>Le <strong>priapisme</strong> est une <strong>érection involontaire et prolongée de plus de 4 heures</strong>, en général <strong>douloureuse</strong>, et survenant en dehors de toute stimulation sexuelle.</p>"},{"i":"c9bb0020e84c","n":126,"o":"126-5","u":"Identifier une urgence","t":"Savoir identifier un priapisme","q":"Quels sont les résultats attendus des gaz du sang caverneux pour distinguer un priapisme ischémique d'un priapisme non ischémique ?","a":"<ul><li>En cas de <strong>priapisme ischémique</strong> : <strong>PaO₂ &lt; 30 mmHg</strong>, <strong>PaCO₂ &gt; 60 mmHg</strong>, <strong>pH &lt; 7,25</strong> (traduisant une hypoxie et une acidose).</li><li>En cas de <strong>priapisme non ischémique</strong> : PaO₂ &gt; 50 mmHg, PaCO₂ &lt; 40 mmHg, pH &gt; 7,35.</li></ul>"},{"i":"0f7e90657e45","n":126,"o":"126-7","u":"Examens complémentaires","t":"Connaître le bilan de première intention d’une dysfonction érectile","q":"Quel est le bilan biologique minimal systématiquement recommandé dans la dysfonction érectile ?","a":"<p>Le bilan biologique minimal systématiquement recommandé comprend :</p><ul><li>Une <strong>glycémie à jeun</strong>.</li><li>Un <strong>bilan lipidique</strong> (cholestérol total, HDL, triglycérides).</li></ul>"},{"i":"5a9267e81732","n":126,"o":"126-7","u":"Examens complémentaires","t":"Connaître le bilan de première intention d’une dysfonction érectile","q":"Quels bilans complémentaires sont envisagés selon le contexte clinique spécifique chez un patient présentant un trouble de l'érection ?","a":"<p>Des bilans complémentaires sont envisagés selon le contexte :</p><ul><li>Si le patient est <strong>diabétique</strong> : ajout de l'<strong>HbA1c</strong>.</li><li>Si le patient a <strong>plus de 50 ans</strong> et présente des <strong>signes de déficit en testostérone</strong> : dosage de la <strong>testostéronémie totale et biodisponible</strong>.</li><li>Selon l'<strong>examen prostatique</strong> ou si une <strong>androgénothérapie est envisagée</strong> : dosage du <strong>PSA total</strong>.</li><li>En l'absence de bilan récent (moins de 5 ans) : <strong>NFS, créatininémie, ionogramme, bilan hépatique</strong>.</li></ul>"},{"i":"c30ea4d2c0cb","n":126,"o":"126-7","u":"Examens complémentaires","t":"Connaître le bilan de première intention d’une dysfonction érectile","q":"Quel est l'objectif du bilan paraclinique de première intention face à un trouble de l'érection ?","a":"<p>L'objectif du bilan paraclinique de première intention n'est <strong>pas de confirmer le diagnostic de dysfonction érectile</strong>, qui est clinique par l'interrogatoire. Il vise à <strong>dépister les facteurs de risque cardio-vasculaire</strong> (FRCV) et les éventuelles <strong>comorbidités sous-jacentes</strong>.</p>"}]};